import {EXPECTED} from './animation/model.mjs';
const buttons=[...document.querySelectorAll('[data-record-focus]')];
const image=document.getElementById('hero-hornet'),map=document.getElementById('hero-map');
const reduced=matchMedia('(prefers-reduced-motion:reduce)');
let selected='region',geometry=null,error=null,feedback=null;
function outline(feature){if(feature.geometry?.type!=='Polygon')throw new Error('地區輪廓格式不符。');const[w,s,e,n]=feature.bbox,c=Math.cos((s+n)/2*Math.PI/180),dx=(e-w)*c,dy=n-s,k=Math.min(470/dx,240/dy),x=260-dx*k/2,y=151-dy*k/2;return feature.geometry.coordinates.map(r=>r.map(([lon,lat],i)=>`${i?'L':'M'}${(x+(lon-w)*c*k).toFixed(3)} ${(y+(n-lat)*k).toFixed(3)}`).join(' ')+'Z').join(' ');}
function selectFocus(next,{animate=false}={}){if(!['region','coordinates'].includes(next))return;selected=next;for(const b of buttons)b.setAttribute('aria-pressed',String(b.dataset.recordFocus===selected));document.getElementById('region-field').dataset.active=String(selected==='region');document.getElementById('coordinate-field').dataset.active=String(selected==='coordinates');map.dataset.focus=selected;document.getElementById('record-reading').textContent=selected==='region'?'原句能指出報導地區是澤西島；本示例未提供精確發現位置。':'這是區域地理編碼，只要求落在報導區域內；精確發現位置仍未提供。';feedback?.cancel();if(animate&&!reduced.matches){const target=selected==='region'?map:document.getElementById('coordinate-field');feedback=target.animate([{opacity:.55},{opacity:1}],{duration:180,easing:'ease-out'});}}
buttons.forEach(b=>{b.disabled=false;b.addEventListener('click',e=>selectFocus(b.dataset.recordFocus,{animate:e.detail>0}));});selectFocus(selected);
async function load(){try{const r=await fetch('./animation/data/jersey-boundary-v01.json');if(!r.ok)throw new Error('地區輪廓未載入。');geometry=await r.json();document.getElementById('hero-island').setAttribute('d',outline(geometry));}catch(e){error=e.message;map.dataset.fallback="static-boundary";}}
window.RecordHero={selectFocus,getState:()=>({ready:true,selected,geometryReady:!!geometry,error,imageReady:image.complete&&image.naturalWidth>0,imageSrc:image.getAttribute('src'),geometryType:geometry?.geometry?.type,geometryVertexCount:geometry?.geometry?.coordinates[0].length,mapPath:document.getElementById('hero-island').getAttribute('d'),markerCount:0,preciseSightingKnown:false,expectedKind:EXPECTED.kind,expectedRegion:EXPECTED.region,modelRun:false})};load();
